// Basic LLM Chain (Ollama) returns { text: "<preamble>```json\n{...}\n```" }
// Strip markdown fences/preamble, parse the JSON.
const raw = $input.first().json;
let rawText = raw.text ?? '';
const fenceMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fenceMatch) {
  rawText = fenceMatch[1];
} else {
  const start = rawText.indexOf('{');
  const end = rawText.lastIndexOf('}');
  if (start !== -1 && end !== -1) rawText = rawText.slice(start, end + 1);
}
let parsed;
try {
  parsed = JSON.parse(rawText.trim());
} catch (e) {
  throw new Error('Could not parse JSON from Ollama output: ' + rawText);
}
return { json: parsed };

