// Clean numbers, validate math, and flatten for downstream routing.
const raw = $input.first().json;

const toNum = (val) => {
  if (val === null || val === undefined || val === '') return 0;
  const cleaned = parseFloat(String(val).replace(/[^-0-9.]/g, ''));
  return isNaN(cleaned) ? 0 : cleaned;
};

const sub_total = toNum(raw.Sub_Total);
const tax = toNum(raw.Tax);
const shipping_fee = toNum(raw.Shipping_Fee);
const discount = toNum(raw.Discount);
const grand_total = toNum(raw.Grand_Total);

const calculated = (sub_total + tax + shipping_fee) - discount;
const math_valid = Math.abs(calculated - grand_total) < 0.05;

const line_items = (raw.Line_Items || []).map((i) => ({
  description: i.Description, qty: toNum(i.Qty), price: toNum(i.Price), total: toNum(i.Total),
}));

// Deterministic party extraction from the PDF text (small local models swap Vendor/Client).
// Vendor = top-left name block (the biller). Client = value under a "Bill To"-style label.
const norm = (s) => String(s || '').trim().toLowerCase();
const PLACEHOLDERS = ['unknown', 'n/a', 'na', 'none', 'null', '-', '--', ''];
const isBlank = (s) => PLACEHOLDERS.includes(norm(s));
let docText = '';
try { docText = String($('Extract from File').first().json.text || ''); } catch (e) { docText = ''; }
const lines = docText.split('\n').map((l) => l.trim()).filter(Boolean);
const LABEL = /^(bill(?:ed)?\s*to|invoice\s*to|sold\s*to|customer(?:\s*name)?|client(?:\s*name)?|paid\s*by|to)\b\s*:?\s*(.*)$/i;
const HEADERS = /^(invoice|purchase order|receipt|tax invoice|bill|po|page\s*\d+)$/i;

let labelFound = false;
let labelClient = '';
for (let i = 0; i < lines.length; i++) {
  const m = lines[i].match(LABEL);
  if (!m) continue;
  labelFound = true;
  labelClient = m[2] ? m[2].trim() : (lines[i + 1] || '').trim();
  break;
}

// Vendor: top-left block, the first line that is not a document-type heading, email, or phone.
const topLine = lines.find((l) => !HEADERS.test(l) && !/@/.test(l) && !/^[+\d(][\d\s().+-]{6,}$/.test(l)) || '';
let vendor = String(raw.Vendor || '').trim();
if (isBlank(vendor) && topLine) vendor = topLine;

let clientName;
if (labelFound) {
  clientName = isBlank(labelClient) ? '' : labelClient;
} else {
  clientName = String(raw.Client_Name || '').trim();
  if (isBlank(clientName) || /@/.test(clientName)) clientName = '';
}
// A client can never be the biller.
if (clientName && (norm(clientName) === norm(vendor) || (topLine && norm(clientName) === norm(topLine)))) clientName = '';

const docType = ['PO', 'Invoice', 'Receipt'].includes(raw.Document_Type) ? raw.Document_Type : 'Other';

return { json: {
  document_type: docType,
  vendor,
  client_name: clientName,
  document_number: raw.Document_Number || '',
  date: raw.Date || '',
  due_date: raw.Due_Date || '',
  email: raw.Email || '',
  sub_total, tax, shipping_fee, discount, grand_total,
  line_items,
  math_valid,
  math_error_details: math_valid ? 'None' : `AI said ${grand_total}, math says ${calculated.toFixed(2)}`,
} };

// Fuzzy-match this invoice against open POs from the same vendor.
// Exact (amount within $1) -> auto-reconcile. Close (within 10%) ->
// AI-explainable flag for quick human confirmation. No match -> full review.
const invoice = $('Parse & Validate').first().json;
const openPOs = $input.all();

if (!invoice.math_valid) {
  return [{ json: { ...invoice, match_result: 'needs_review', match_reason: 'Math does not reconcile: ' + invoice.math_error_details } }];
}

let best = null;
let bestDiff = Infinity;
for (const po of openPOs) {
  const poTotal = parseFloat(po.json['Grand Total']) || 0;
  const diff = Math.abs(poTotal - invoice.grand_total);
  if (diff < bestDiff) { bestDiff = diff; best = po.json; }
}

if (!best) {
  return [{ json: { ...invoice, match_result: 'no_match', match_reason: 'No open PO found for this vendor.' } }];
}
if (bestDiff < 1) {
  return [{ json: { ...invoice, match_result: 'matched', match_reason: 'Exact amount match against PO ' + best['PO Number'], matched_po_number: best['PO Number'] } }];
}
const pctDiff = (bestDiff / (best['Grand Total'] || 1)) * 100;
if (pctDiff < 10) {
  return [{ json: { ...invoice, match_result: 'needs_confirmation', match_reason: `Invoice differs from PO ${best['PO Number']} by $${bestDiff.toFixed(2)} (${pctDiff.toFixed(1)}%) — likely shipping/rounding, needs quick confirmation.`, matched_po_number: best['PO Number'] } }];
}
return [{ json: { ...invoice, match_result: 'needs_review', match_reason: `Closest PO (${best['PO Number']}) differs by $${bestDiff.toFixed(2)} — too large to auto-reconcile.` } }];

const doc = $input.first().json;
const items = (doc.line_items && doc.line_items.length)
  ? doc.line_items
  : [{ description: '(no line items extracted)', qty: '', price: '', total: '' }];
return items.map((item) => ({
  json: {
    date: doc.date,
    document_number: doc.document_number,
    vendor: doc.vendor,
    client_name: doc.client_name,
    item_description: item.description,
    qty: item.qty,
    unit_price: item.price,
    line_total: item.total,
    grand_total: doc.grand_total,
    status: 'Open',
    reason: '',
    record_type: 'PO',
  }
}));

